/* Шаблоны для строк, собираемых кодом из кусков (confirm-окна и т.п.) */
window.I18N_AUTO_PATS = [
  [/^(\d+)с назад$/, function (l, t, m) { return l === 'en' ? m[1] + 's ago' : m[1] + ' san əvvəl'; }],
  [/^(\d+) активных$/, function (l, t, m) { return l === 'en' ? m[1] + ' active' : m[1] + ' aktiv'; }],
  [/^(?:🎖️? ?)?Гимн будет включён на (.+?)\.?\s*Продолжить\?$/s, function (l, t, m) { var x = t(m[1]); return l === 'en' ? '🎖️ The anthem will be played on ' + x + '.\n\nContinue?' : '🎖️ Himn işə salınacaq — ' + x + '.\n\nDavam edilsin?'; }],
  [/^(?:🕯 ?)?Минута молчания будет запущена на (.+?)\s*вне расписания\.\s*Продолжить\?$/s, function (l, t, m) { var x = t(m[1]); return l === 'en' ? '🕯 The minute of silence will start on ' + x + ' outside the schedule.\n\nContinue?' : '🕯 Sükut dəqiqəsi cədvəldən kənar başlayacaq — ' + x + '.\n\nDavam edilsin?'; }],
  [/^(?:🚨 ?)?Сигнал ТРЕВОГИ будет запущен на (.+?) и будет играть в цикле, пока не нажмёшь обычный СТОП\.\s*Продолжить\?$/s, function (l, t, m) { var x = t(m[1]); return l === 'en' ? '🚨 The ALARM signal will start on ' + x + ' and will loop until you press the regular STOP.\n\nContinue?' : '🚨 HƏYƏCAN siqnalı başlayacaq — ' + x + ' və adi DAYAN düyməsinə basana qədər dövrə ilə oxunacaq.\n\nDavam edilsin?'; }],
  [/^(?:🎖 ?)?Zəfər Günü будет запущен на (.+?)\.\s*Продолжить\?$/s, function (l, t, m) { var x = t(m[1]); return l === 'en' ? '🎖 Zəfər Günü will start on ' + x + '.\n\nContinue?' : '🎖 Zəfər Günü başlayacaq — ' + x + '.\n\nDavam edilsin?'; }],
  [/^(?:🎵 ?)?National Music Day будет запущен на (.+?)\.\s*Продолжить\?$/s, function (l, t, m) { var x = t(m[1]); return l === 'en' ? '🎵 National Music Day will start on ' + x + '.\n\nContinue?' : '🎵 National Music Day başlayacaq — ' + x + '.\n\nDavam edilsin?'; }],
  [/^(?:⏸ ?)?Автоматические звонки по расписанию будут ОСТАНОВЛЕНЫ на (.+?)\.\s*Не забудь включить обратно\.\s*Продолжить\?$/s, function (l, t, m) { var x = t(m[1]); return l === 'en' ? '⏸ Automatic scheduled bells will be STOPPED on ' + x + '.\nDo not forget to turn them back on.\n\nContinue?' : '⏸ Cədvəl üzrə avtomatik zənglər DAYANDIRILACAQ — ' + x + '.\nYenidən aktiv etməyi unutmayın.\n\nDavam edilsin?'; }],
  [/^(?:🎤 ?)?То, что ты сейчас скажешь, будет проиграно на громкой связи кампуса\.\s*Продолжить\?$/s, function (l) { return l === 'en' ? '🎤 What you say now will be played over the campus PA.\n\nContinue?' : '🎤 İndi dediyiniz kampusun səsgücləndiricisində səslənəcək.\n\nDavam edilsin?'; }],
  [/^(▶️ Включить|⏸ Выключить) (.+?) на ВСЕХ доступных кампусах\?\s*Продолжить\?$/s, function (l, t, m) { var on = m[1].indexOf('Включить') > -1, x = t(m[2]); return l === 'en' ? (on ? '▶️ Turn on ' : '⏸ Turn off ') + x + ' on ALL available campuses?\n\nContinue?' : (on ? '▶️ ' : '⏸ ') + 'BÜTÜN əlçatan kampuslarda ' + x + (on ? ' aktiv edilsin?' : ' söndürülsün?') + '\n\nDavam edilsin?'; }],
  [/^Удалить (файл|папку) «(.+)»\?(.*)$/s, function (l, t, m) { var w = m[1] === 'файл' ? (l === 'en' ? 'file' : 'faylı') : (l === 'en' ? 'folder' : 'qovluğu'); var tail = m[3] ? ' ' + t(m[3].trim()) : ''; return l === 'en' ? 'Delete ' + w + ' «' + m[2] + '»?' + tail : '«' + m[2] + '» ' + w + ' silinsin?' + tail; }],
  [/^Удалить (\d+) треков\??\s*(.*)$/s, function (l, t, m) { var tail = m[2] ? ' ' + t(m[2]) : ''; return l === 'en' ? 'Delete ' + m[1] + ' tracks?' + tail : m[1] + ' trek silinsin?' + tail; }],
  [/^(\d+) (?:перемена|перемены)(.*)$/s, function (l, t, m) { var n = +m[1], suf = { 1: 'ci', 2: 'ci', 3: 'cü', 4: 'cü', 5: 'ci', 6: 'cı', 7: 'ci', 8: 'ci', 9: 'cu' }[n] || 'ci'; var tail = m[2] ? t(m[2]) : ''; return l === 'en' ? 'Break ' + n + tail : n + '-' + suf + ' fasilə' + tail; }],
  [/^(\d+) (треков|трека|трек)(.*)$/s, function (l, t, m) { var n = +m[1], tail = m[3] ? t(m[3]) : ''; return l === 'en' ? n + (n === 1 ? ' track' : ' tracks') + tail : n + ' trek' + tail; }],
  [/^Громкость (.+)$/s, function (l, t, m) { return (l === 'en' ? 'Volume ' : 'Səs səviyyəsi ') + m[1]; }]
];
